import urllib.request
ua='Mozilla/5.0'
for url in ['https://www.ncbi.nlm.nih.gov/books/NBK562255/']:
    req=urllib.request.Request(url, headers={'User-Agent':ua})
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            txt=r.read(10000).decode('utf-8','ignore')
            print(r.status, r.headers.get('content-type'))
            for s in ['primary','lymphocytic','autoimmune','granulomatous']:
                i=txt.lower().find(s)
                print(s, i, txt[i-300:i+500] if i!=-1 else '')
    except Exception as e:

